import{describe,it,expect}from"vitest";import{CINEMA_MILESTONES,CINEMA_ERAS,filterMilestonesByEra,calculateFilmstripOffset,getActiveFrameIndex,getTimelineStats}from"../../frontend/indian-cinema-timeline/script.js";describe("Indian Cinema Milestones Dataset Integrity",()=>{it("contains at least 8 verified milestones (has 10)",()=>{expect(CINEMA_MILESTONES.length).toBeGreaterThanOrEqual(8),expect(CINEMA_MILESTONES.length).toBe(10)}),it("verifies chronological order of years from 1913 to 2022",()=>{expect(CINEMA_MILESTONES[0].year).toBe(1913),expect(CINEMA_MILESTONES[CINEMA_MILESTONES.length-1].year).toBe(2022);for(let e=0;e<CINEMA_MILESTONES.length-1;e++)expect(CINEMA_MILESTONES[e].year).toBeLessThanOrEqual(CINEMA_MILESTONES[e+1].year)}),it("every milestone contains required verified fields",()=>{CINEMA_MILESTONES.forEach((e,t)=>{expect(e,`Milestone ${t} missing id`).toHaveProperty("id"),expect(e,`Milestone ${t} missing year`).toHaveProperty("year"),expect(e,`Milestone ${t} missing title`).toHaveProperty("title"),expect(e,`Milestone ${t} missing era`).toHaveProperty("era"),expect(e,`Milestone ${t} missing industry`).toHaveProperty("industry"),expect(e,`Milestone ${t} missing pioneer`).toHaveProperty("pioneer"),expect(e,`Milestone ${t} missing summary`).toHaveProperty("summary"),expect(e,`Milestone ${t} missing details`).toHaveProperty("details"),expect(e,`Milestone ${t} missing significance`).toHaveProperty("significance"),expect(e,`Milestone ${t} missing svgIcon`).toHaveProperty("svgIcon"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.summary).toBe("string"),expect(e.summary.trim().length).toBeGreaterThan(0)})}),it("does not contain copyrighted image paths (uses SVG icons)",()=>{CINEMA_MILESTONES.forEach(e=>{expect(e).not.toHaveProperty("image"),expect(e).not.toHaveProperty("posterUrl"),expect(typeof e.svgIcon).toBe("string")})})}),describe("Era Filtering & Helper Functions",()=>{it('returns all milestones when filter is "All Eras"',()=>{const e=filterMilestonesByEra(CINEMA_MILESTONES,"All Eras");expect(e.length).toBe(CINEMA_MILESTONES.length)}),it("filters milestones correctly by era name",()=>{const e=filterMilestonesByEra(CINEMA_MILESTONES,"Silent Era");expect(e.length).toBe(1),expect(e[0].year).toBe(1913);const t=filterMilestonesByEra(CINEMA_MILESTONES,"Golden Age");expect(t.length).toBe(1),expect(t[0].year).toBe(1951)}),it("calculates filmstrip horizontal scroll offset correctly",()=>{expect(calculateFilmstripOffset(0,1e3,3e3)).toBe(0),expect(calculateFilmstripOffset(50,1e3,3e3)).toBe(-1e3),expect(calculateFilmstripOffset(100,1e3,3e3)).toBe(-2e3)}),it("calculates active frame index based on scroll percentage",()=>{expect(getActiveFrameIndex(0,10)).toBe(0),expect(getActiveFrameIndex(25,10)).toBe(2),expect(getActiveFrameIndex(99,10)).toBe(9),expect(getActiveFrameIndex(100,10)).toBe(9)}),it("computes timeline statistics correctly",()=>{const e=getTimelineStats(CINEMA_MILESTONES);expect(e.totalMilestones).toBe(10),expect(e.yearSpan).toBe("1913 - 2022"),expect(e.erasCount).toBeGreaterThanOrEqual(8)})});